@startuml

class Employee {
  + identifyingNumber : string
  + name : string
  + address : string
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + name : string
  + identifyingNumber : string
  + address : string
  + phone : string
}

class AssemblyService {
  + kmsAtTime : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

Employee "1" -- "*" AssemblyService : is responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "1..*" PartAccessory : fits
PartAccessory "*" -- "*" Car : fits in

Owner "1" -- "0..*" Car : owns

@enduml

